   145	static int idn2_to_unicode_8z8z(const char *src, char **dst, unsigned flags)
   146	{
   147	        int rc, run;
   148	        size_t out_len = 0;
   149	        const char *e, *s;
   150	        char *p = NULL;
   151	
   152	        for (run = 0; run < 2; run++) {
   153	                if (run) {
   154	                        p = malloc(out_len + 1);
   155	                        if (!p)
   156	                                return IDN2_MALLOC;
   157	                        *dst = p;
   158	                }
   159	
   160	                out_len = 0;
   161	                for (e = s = src; *e; s = e) {
   162	                        while (*e && *e != '.')
   163	                                e++;
   164	
   165	                        if (e - s > 4 && (s[0] == 'x' || s[0] == 'X') && (s[1] == 'n' || s[1] == 'N') && s[2] == '-' && s[3] == '-') {
   166	                                size_t u32len = IDN2_LABEL_MAX_LENGTH * 4;
   167	                                uint32_t u32[IDN2_LABEL_MAX_LENGTH * 4];
   168	                                uint8_t u8[IDN2_LABEL_MAX_LENGTH + 1];
   169	                                size_t u8len;
   170	
   171	                                rc = _idn2_punycode_decode(e - s - 4, s + 4, &u32len, u32, NULL);
   172	                                if (rc != IDN2_OK)
   173	                                        return rc;
   174	
   175	                                u8len = sizeof(u8);
   176	                                if (u32_to_u8(u32, u32len, u8, &u8len) == NULL)
   177	                                        return IDN2_ENCODING_ERROR;
   178	                                u8[u8len] = '\0';
   179	
   180	                                if (run)
   181	                                        memcpy(*dst + out_len, u8, u8len);
   182	                                out_len += u8len;
   183	                        } else {
   184	                                if (run)
   185	                                        memcpy(*dst + out_len, s, e - s);
   186	                                out_len += e - s;
   187	                        }
   188	
   189	                        if (*e) {
   190	                                e++;
   191	                                if (run)
   192	                                        (*dst)[out_len] = '.';
   193	                                out_len++;
   194	                        }
   195	                }
   196	        }
   197	
   198	        (*dst)[out_len] = 0;
   199	
   200	        return IDN2_OK;
   201	}
   202	#endif
