   204	/**
   205	 * gnutls_idna_reverse_map:
   206	 * @input: contain the ACE (IDNA) formatted domain name
   207	 * @ilen: the length of the provided string
   208	 * @out: the result in an null-terminated allocated UTF-8 string
   209	 * @flags: should be zero
   210	 *
   211	 * This function will convert an ACE (ASCII-encoded) domain name to a UTF-8 domain name.
   212	 *
   213	 * If GnuTLS is compiled without IDNA support, then this function
   214	 * will return %GNUTLS_E_UNIMPLEMENTED_FEATURE.
   215	 *
   216	 * Note also, that this function will return an empty string if an
   217	 * empty string is provided as input.
   218	 *
   219	 * Returns: A negative error code on error, or 0 on success.
   220	 *
   221	 * Since: 3.5.8
   222	 **/
   223	int gnutls_idna_reverse_map(const char *input, unsigned ilen, gnutls_datum_t *out, unsigned flags)
   224	{
   225	        char *u8 = NULL;
   226	        int rc, ret;
   227	        gnutls_datum_t istr;
   228	
   229	        if (ilen == 0) {
   230	                out->data = (uint8_t*)gnutls_strdup("");
   231	                out->size = 0;
   232	                if (out->data == NULL)
   233	                        return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
   234	                return 0;
   235	        }
   236	
   237	        ret = _gnutls_set_strdatum(&istr, input, ilen);
   238	        if (ret < 0) {
   239	                gnutls_assert();
   240	                return ret;
   241	        }
   242	
   243	        /* currently libidn2 just converts single labels, thus a wrapper function */
   244	        rc = idn2_to_unicode_8z8z((char*)istr.data, &u8, 0);
   245	        if (rc != IDN2_OK) {
   246	                gnutls_assert();
   247	                _gnutls_debug_log("unable to convert ACE name '%s' to UTF-8 format: %s\n", istr.data, idn2_strerror(rc));
   248	                ret = GNUTLS_E_INVALID_UTF8_STRING;
   249	                goto fail;
   250	        }
   251	
   252	        if (gnutls_malloc != malloc) {
   253	                ret = _gnutls_set_strdatum(out, u8, strlen(u8));
   254	        } else  {
   255	                out->data = (unsigned char*)u8;
   256	                out->size = strlen(u8);
   257	                u8 = NULL;
   258	                ret = 0;
   259	        }
   260	 fail:
   261	        idn2_free(u8);
   262	        gnutls_free(istr.data);
   263	        return ret;
   264	}
