   284	int _gnutls_idna_email_map(const char *input, unsigned ilen, gnutls_datum_t *output)
   285	{
   286	        const char *p = input;
   287	
   288	        while(*p != 0 && *p != '@') {
   289	                if (!c_isprint(*p))
   290	                        return gnutls_assert_val(GNUTLS_E_INVALID_UTF8_EMAIL);
   291	                p++;
   292	        }
   293	
   294	        if (_gnutls_str_is_print(input, ilen)) {
   295	                return _gnutls_set_strdatum(output, input, ilen);
   296	        }
   297	
   298	        if (*p == '@') {
   299	                unsigned name_part = p-input;
   300	                int ret;
   301	                gnutls_datum_t domain;
   302	
   303	                ret = gnutls_idna_map(p+1, ilen-name_part-1, &domain, 0);
   304	                if (ret < 0)
   305	                        return gnutls_assert_val(ret);
   306	
   307	                output->data = gnutls_malloc(name_part+1+domain.size+1);
   308	                if (output->data == NULL) {
   309	                        gnutls_free(domain.data);
   310	                        return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
   311	                }
   312	                memcpy(output->data, input, name_part);
   313	                output->data[name_part] = '@';
   314	                memcpy(&output->data[name_part+1], domain.data, domain.size);
   315	                output->data[name_part+domain.size+1] = 0;
   316	                output->size = name_part+domain.size+1;
   317	                gnutls_free(domain.data);
   318	                return 0;
   319	        } else {
   320	                return gnutls_assert_val(GNUTLS_E_INVALID_UTF8_EMAIL);
   321	        }
   322	}
